head.script:
// 원본 : cm/cert/sample/initech-cert-sample2.html (정적 HTML 샘플) → /ui/sample/template/SMPCRT10000.xml

/*
 * 화면 동작
 * 1. 화면 로딩시 $c.cert.loadModule 로 공동인증서 모듈을 초기화한다(키패드 z-index 보정 포함).
 *    벤더 스크립트(라온 TransKey·이니텍 crosswebex6·initech-common)는 config.xml engine 모듈로 셸이 정적 로드한다.
 * 2. 「공동인증서 인증」 클릭시 인증서 팝업 → 전자서명 → 서버 검증(로그인 처리) → 성공 콜백에 결과 표시
 * 3. 「인증서 검증」 클릭시 인증서 팝업 → 전자서명 → OCSP 실시간 폐기여부 확인 → 콜백에서 body.result 로 판정
 * 4. 「인증서 등록」 클릭시 담당자 정보 검증 → 인증서 팝업 → 전자서명 + 담당자 정보를 같은 요청으로 전송 → 결과 표시
 * 5. 「가상키보드 사용」 체크 변경시 이니텍 설정(cwui_conf)의 라온 키패드 USE 값을 바꾸고 sessionStorage 에 보관한다.
 *    인증서 팝업을 이미 연 뒤에는 이니텍 UI 가 키패드 선택을 캐시하므로 새로고침 안내를 띄운다.
 *
 * 담긴 패턴
 * - 공동인증서 공통 ($c.cert) — loadModule(모듈 초기화 + 키패드 z-index 보정, 벤더 미로드면 등록 안내 오류) · auth(전자서명 호출,
 *   opt.params 동봉·opt.useTranskey 로 팝업 직전 키패드 설정 반영). 키패드 id 는 공통(INITECH_INFO), 스크립트 경로는 config.xml 이 보유한다.
 * - 벤더 콜백(initech-common.js → callback(res)) 수신을 4구역 "서브미션 콜백 영역" 에 배치
 * - 담당자 정보 검증 ($c.validate.validateDataCollect — required·maxLengthB·format phone/email)
 * - 화면 설정 보관 ($c.util.setSessionStorage/getSessionStorage — 저장 불가 환경은 공통이 흡수)
 * - 알림 ($c.win.alert await) · 새로고침 ($c.win.reload) · 진입점 try/catch ($c.exception.handleError)
 * - 화면 상태 표시 (w2:textbox setValue + show/hide, 성공 blue / 실패 red 클래스 전환)
 *
 * 이 화면이 쓰는 벤더 의존 모듈 (gcc 밖 — 상세는 cm/gcc/cert.xml 머리 주석)
 * - /resources/js/common/initech-common.js : 전자서명(PKCS7SignedData) + params 를 FormData 로 POST 한다.
 *   콜백은 HTTP 2xx 에서만 호출되고, 4xx/5xx·팝업 취소는 벤더 알림창(INI_ALERT)만 뜬다.
 *   그래서 버튼을 누를 때마다 결과 영역을 먼저 비운다. 이 통신은 $c.sbm 을 타지 않는다.
 * - API 경로에는 app.api.prefix(/api/discls)가 포함된다. 프리픽스를 바꾸면 벤더 스크립트의 하드코딩 경로도 함께 고친다.
 *
 * 변환 샘플과 달라진 곳 (원본 HTML 대비)
 * - <script src> 5개는 config.xml/config.js 의 engine 모듈(정적 로드)로 옮겼다. crosswebex6.js 가 로드 즉시 document.write 로
 *   하위 스크립트를 끌어오기 때문에 화면에서 동적 로드하면 문서가 지워진다 — 그래서 $c.cert 는 동적 로드를 하지 않는다.
 *   모듈 초기화·키패드 z-index CSS·cwui_conf 키패드 설정 조작은 $c.cert 공통으로 옮겼다.
 * - 항목별 "빈값 → alert → focus → return" 4건과 전화번호·이메일 정규식 검사를 validateDataCollect 한 건으로 통합했다.
 * - alert/console.log/location.reload/sessionStorage 직접 호출을 $c.win.alert·$c.win.reload·$c.util.*SessionStorage 로 바꿨다.
 * - 원시 DOM/jQuery 조작($("#result")…)을 w2:textbox 컴포넌트 API(setValue/show/hide/addClass)로 바꿨다.
 * - var 를 const/let 으로 바꿨다.
 *
 * 복사해서 쓰는 순서
 * 1. 파일명과 meta_screenId 를 실제 화면ID 로 변경
 * 2. API_URL 3종을 실 API 로 교체 (인증 URL 은 서버가 accessToken 쿠키를 내려주는 로그인 처리 URL)
 * 3. dma_chrgInfo 키·입력 마크업·validateRegister 의 fields 를 업무 항목으로 교체
 * 4. 콜백 3종의 응답 필드(body.result·certInfo·serialNumber 등)를 서버 DTO 에 맞게 조정
 * 5. 키패드 id 가 다르면 $c.cert 의 INITECH_INFO 를, 벤더 스크립트 경로가 다르면 config.xml/config.js 를 고친다
 */


///////// 1. 변수 및 선언 영역 /////////

scwin.screenId = "SMPCRT10000";

// 이 화면이 호출하는 API — 공통(vendor/SW/initech/**)과 업무(info/cert/insert)
scwin.API_URL = {
    auth     : "/api/discls/guest/auth/inisafe-sign-login-processing",   // 전자서명 검증 + 로그인 처리
    verify   : "/api/discls/vendor/SW/initech/cert/verify",              // OCSP 인증서 검증 (공통)
    register : "/api/discls/info/cert/insert"                            // 인증서 등록 (업무 — 담당자 정보 동봉)
};

// 체크박스 상태 보관 키 — 새로고침으로 반영할 때 상태를 유지한다
scwin.TRANSKEY_PREF_KEY = "initechSampleUseTranskey";

// 이 화면에서 인증서 팝업을 한 번이라도 열었는지 (이니텍 UI 가 첫 팝업의 키패드 선택을 캐시하므로 안내 조건)
scwin.certPopupOpened = false;


///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 15
 * @description 페이지로드
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    // 진입점 표준 오류 처리 — 내부 함수는 예외를 위로 던지고, 진입점의 catch 한 줄로 수렴한다.
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "SMPCRT10000.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 09. 15
 * @description 초기화. 공동인증서 모듈을 준비하고 체크박스 상태를 복원한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 모듈 초기화 안내를 표시할 컴포넌트 (onStatus)
 * @param
 * @returns
 * @hidden N
*/
scwin.init = async function () {
    scwin.clearResult();

    // 벤더 스크립트 확인(셸이 정적 로드) → 키패드 z-index 보정 → 공동인증서 모듈 초기화 (PC 만)
    await $c.cert.loadModule({
        onStatus : function (message) {
            txb_moduleStatus.setValue(message);
            txb_moduleStatus.show();
        }
    });

    // 저장된 가상키보드 사용 여부 복원
    chk_useTranskey.setValue(scwin.loadTranskeyPref() ? "Y" : "");
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_certAuth_onclick
 * @author Inswave
 * @date 2026. 09. 15
 * @description 공동인증서 인증 버튼 클릭. 전자서명 후 서버 검증(로그인 처리), 성공 시 인증 토큰(accessToken 쿠키) 발급.
 *
 * 로그인 실패는 401 로 돌아와 콜백에 오지 않고 벤더 알림창에 사유가 뜬다(성공만 콜백으로 온다).
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_certAuth_onclick = async function () {
    try {
        scwin.clearResult();
        scwin.beforeCertPopup();

        await $c.cert.auth(scwin.API_URL.auth, scwin.certAuthCallback, { useTranskey : scwin.useTranskey() });
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "SMPCRT10000.btn_certAuth_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_certVerify_onclick
 * @author Inswave
 * @date 2026. 09. 15
 * @description 인증서 검증 버튼 클릭. 정상 등록된 인증서인지 OCSP 로 실시간 폐기여부를 확인한다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_certVerify_onclick = async function () {
    try {
        scwin.clearResult();
        scwin.beforeCertPopup();

        await $c.cert.auth(scwin.API_URL.verify, scwin.certVerifyCallback, { useTranskey : scwin.useTranskey() });
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "SMPCRT10000.btn_certVerify_onclick" });
    }
};

/**
 * @event
 * @name scwin.btn_certRegister_onclick
 * @author Inswave
 * @date 2026. 09. 15
 * @description 인증서 등록 버튼 클릭. 담당자 정보를 검증한 뒤 전자서명과 같은 요청으로 보낸다.
 *
 * 등록은 업무 API 라 검증 실패는 400(BusinessException)으로 돌아오며 콜백이 아니라 벤더 알림창에 안내 문구가 뜬다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_certRegister_onclick = async function () {
    try {
        if (!await scwin.validateRegister()) return;

        scwin.clearResult();
        scwin.beforeCertPopup();

        // dataMap 키 이름이 곧 서버 파라미터명이다 (PKCS7SignedData 와 같은 FormData 에 담긴다)
        await $c.cert.auth(scwin.API_URL.register, scwin.certRegisterCallback, {
            params      : dma_chrgInfo.getJSON(),
            useTranskey : scwin.useTranskey()
        });
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "SMPCRT10000.btn_certRegister_onclick" });
    }
};

/**
 * @event
 * @name scwin.chk_useTranskey_onchange
 * @author Inswave
 * @date 2026. 09. 15
 * @description 가상키보드 사용 여부 변경. 이니텍 설정에 반영하고 보관한 뒤, 팝업을 이미 열었으면 새로고침 안내를 띄운다.
 * @param
 * @returns
 * @hidden N
*/
scwin.chk_useTranskey_onchange = function () {
    try {
        const use = scwin.useTranskey();

        scwin.saveTranskeyPref(use);
        $c.cert.setTranskeyUse(use);
        scwin.showTranskeyNotice();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPCRT10000.chk_useTranskey_onchange" });
    }
};

/**
 * @event
 * @name scwin.btn_reload_onclick
 * @author Inswave
 * @date 2026. 09. 15
 * @description 새로고침 안내의 새로고침 버튼 클릭. 이니텍 UI 의 키패드 캐시를 비우기 위해 전체 페이지를 다시 연다.
 * @param
 * @returns
 * @hidden N
*/
scwin.btn_reload_onclick = function () {
    try {
        $c.win.reload();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPCRT10000.btn_reload_onclick" });
    }
};


///////// 4. 서브미션 콜백 영역 (벤더 initech-common.js 콜백) /////////

/**
 * @method
 * @name scwin.certAuthCallback
 * @author Inswave
 * @date 2026. 09. 15
 * @description 공동인증서 로그인(전자서명 검증) 성공 콜백. 연동 확인용 가이드라 화면 이동은 하지 않는다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 성공 후 이동할 화면 ($c.win.moveUrl)
 * @param {Object} res 서버 응답 (CommonResponseDto — message 등)
 * @returns
 * @hidden N
*/
scwin.certAuthCallback = function (res) {
    try {
        scwin.setResult(true, "로그인 성공 — 인증 토큰(accessToken 쿠키) 발급"
            + ($c.util.isEmpty(res.message) ? "" : " : " + res.message));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "SMPCRT10000.certAuthCallback" });
    }
};

/**
 * @method
 * @name scwin.certVerifyCallback
 * @author Inswave
 * @date 2026. 09. 15
 * @description 인증서 검증(OCSP) 결과 콜백.
 *
 * 이 공통 API 는 인증서가 비정상이어도 200 / success=true 다 — 판정은 반드시 body.result 로 한다.
 * @param {Object} res 서버 응답 (body 에 인증서 정보 DTO — result·certInfo)
 * @returns
 * @hidden N
*/
scwin.certVerifyCallback = async function (res) {
    try {
        const cert = res.body || {};
        const message = $c.util.isEmpty(res.message) ? "인증서 상태를 확인할 수 없습니다." : res.message;

        await $c.win.alert(cert.result
            ? "정상 등록된 인증서입니다.\n\n" + message
            : "인증서 확인 실패\n\n" + message);

        scwin.setResult(!!cert.result, "인증서 검증 : " + (cert.certInfo || "-") + " / " + message);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "SMPCRT10000.certVerifyCallback" });
    }
};

/**
 * @method
 * @name scwin.certRegisterCallback
 * @author Inswave
 * @date 2026. 09. 15
 * @description 인증서 등록 성공 콜백. 성공 응답의 body 는 업무 응답 DTO(인증서 식별값·일련번호·담당자 정보)이고 result 필드는 없다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - 표시 필드명 (응답에 담당자 필드가 없으면 "-" 로 표시된다. 서버 DTO 에 맞춘다)
 * @param {Object} res 서버 응답
 * @returns
 * @hidden N
*/
scwin.certRegisterCallback = async function (res) {
    try {
        const data = res.body || {};

        await $c.win.alert("인증서 등록 요청이 정상 처리되었습니다.\n\n일련번호 : " + (data.serialNumber || "-"));

        scwin.setResult(true, "인증서 등록 : " + (data.certInfo || "-")
            + " / 일련번호 : " + (data.serialNumber || "-")
            + "\n담당자명 : " + (data.chrgNm || "-")
            + " / 부서명 : " + (data.chrgDepNm || "-")
            + "\n전화번호 : " + (data.chrgTelNo || "-")
            + " / 이메일 : " + (data.chrgEmail || "-"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "SMPCRT10000.certRegisterCallback" });
    }
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.useTranskey
 * @author Inswave
 * @date 2026. 09. 15
 * @description 가상키보드 사용 여부 (체크박스 상태)
 * @param
 * @returns {Boolean}
 * @hidden N
*/
scwin.useTranskey = function () {
    return chk_useTranskey.getValue() === "Y";
};

/**
 * @method
 * @name scwin.beforeCertPopup
 * @author Inswave
 * @date 2026. 09. 15
 * @description 인증서 팝업을 열기 직전 처리. 새로고침 안내 조건이 되는 "팝업을 연 적 있음" 상태만 기록한다.
 * (키패드 설정 반영은 $c.cert.auth 의 useTranskey 옵션이 팝업 직전에 수행한다)
 * @param
 * @returns
 * @hidden N
*/
scwin.beforeCertPopup = function () {
    scwin.certPopupOpened = true;
};

/**
 * @method
 * @name scwin.showTranskeyNotice
 * @author Inswave
 * @date 2026. 09. 15
 * @description 새로고침 안내 노출 여부 결정. 팝업을 이미 연 뒤에 체크박스를 바꾸면 새로고침해야 확실히 반영된다.
 * @param
 * @returns
 * @hidden N
*/
scwin.showTranskeyNotice = function () {
    if (scwin.certPopupOpened) {
        grp_transkeyNotice.show();
    } else {
        grp_transkeyNotice.hide();
    }
};

/**
 * @method
 * @name scwin.saveTranskeyPref
 * @author Inswave
 * @date 2026. 09. 15
 * @description 체크박스 상태 저장. 저장 불가 환경(프라이빗 모드 등)은 공통이 흡수하므로 화면은 신경 쓰지 않는다.
 * @param {Boolean} use 사용 여부
 * @returns
 * @hidden N
*/
scwin.saveTranskeyPref = function (use) {
    $c.util.setSessionStorage(scwin.TRANSKEY_PREF_KEY, use ? "Y" : "N");
};

/**
 * @method
 * @name scwin.loadTranskeyPref
 * @author Inswave
 * @date 2026. 09. 15
 * @description 체크박스 상태 복원. 저장값이 없으면 기본 미사용.
 * @param
 * @returns {Boolean}
 * @hidden N
*/
scwin.loadTranskeyPref = function () {
    return $c.util.getSessionStorage(scwin.TRANSKEY_PREF_KEY) === "Y";
};

/**
 * @method
 * @name scwin.validateRegister
 * @author Inswave
 * @date 2026. 09. 15
 * @description 인증서 등록 입력값 검증. 필수·byte 길이·전화번호/이메일 형식을 한 건으로 검사한다.
 *
 * 복사해 쓸 때 바꿀 곳
 *  - fields (dataMap 키 기준)
 * @param
 * @returns {Promise<Boolean>} 통과 여부
 * @hidden N
*/
scwin.validateRegister = async function () {
    const formOptions = {
        validateType : "alert",
        checkType    : "single",
        focus        : true,
        fields : {
            chrgNm    : { required : true, maxLengthB : 50,  name : "담당자명" },
            chrgDepNm : { required : true, maxLengthB : 100, name : "담당자 부서명" },
            chrgTelNo : { required : true, maxLengthB : 100, format : "phone", name : "담당자 전화번호" },
            chrgEmail : { required : true, maxLengthB : 100, format : "email", name : "담당자 이메일" }
        }
    };

    return await $c.validate.validateDataCollect(grp_register, formOptions);
};

/**
 * @method
 * @name scwin.setResult
 * @author Inswave
 * @date 2026. 09. 15
 * @description 결과 영역에 성공/실패 문구를 표시한다.
 * @param {Boolean} ok 성공 여부 (true: blue, false: red 클래스)
 * @param {String} text 표시 문구
 * @returns
 * @hidden N
*/
scwin.setResult = function (ok, text) {
    txb_result.removeClass("blue");
    txb_result.removeClass("red");
    txb_result.addClass(ok ? "blue" : "red");
    txb_result.setValue(text);
    txb_result.show();
};

/**
 * @method
 * @name scwin.clearResult
 * @author Inswave
 * @date 2026. 09. 15
 * @description 결과 영역 초기화. 실패(4xx/5xx)·취소 시에는 콜백이 오지 않아 직전 결과가 남으므로 버튼을 누를 때 먼저 비운다.
 * @param
 * @returns
 * @hidden N
*/
scwin.clearResult = function () {
    txb_result.removeClass("blue");
    txb_result.removeClass("red");
    txb_result.setValue("");
    txb_result.hide();
};
